// Code «Revisar los cobros» (11 · Datáfono) · Run Once for All Items
// Recibe una fila del CSV por item (Extract From File, valores en texto) y devuelve un solo item
// { origen, filas, cobros, no_importados, rango }, o para con error si faltan columnas.

const OBLIGATORIAS = ['fecha', 'operacion', 'importe', 'estado'];

// Quién ha disparado el flujo (solo se ejecuta uno de los dos)
function seEjecuto(nombre) {
  try { return $(nombre).isExecuted !== false && $(nombre).all().length > 0; } catch (e) { return false; }
}
const origen = seEjecuto('Subir el CSV del datáfono') ? 'formulario' : 'programado';

// Nombres de columna sin BOM ni espacios y en minúsculas. Un CSV sin filas llega como un item vacío
const filas = $input.all()
  .map(i => Object.fromEntries(Object.entries(i.json).map(([k, v]) => [k.replace(/^﻿/, '').trim().toLowerCase(), v])))
  .filter(f => Object.keys(f).length > 0);

// Con Include Empty Cells desactivado, una celda vacía no trae su columna: se mira la cabecera de todas las filas
if (filas.length) {
  const columnas = new Set(filas.flatMap(f => Object.keys(f)));
  const faltan = OBLIGATORIAS.filter(c => !columnas.has(c));
  if (faltan.length) throw new Error(`Datáfono: faltan columnas en el CSV: ${faltan.join(', ')}`);
}

const limpio = v => (v == null ? '' : String(v).trim());

// dd/mm/aaaa → AAAA-MM-DD, o null si no es una fecha real
function fechaISO(texto) {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(texto);
  if (!m) return null;
  const [d, mes, a] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const f = new Date(Date.UTC(a, mes - 1, d));
  if (f.getUTCFullYear() !== a || f.getUTCMonth() !== mes - 1 || f.getUTCDate() !== d) return null;
  return `${a}-${String(mes).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

// "18,95" o "1.234,56" → 18.95 / 1234.56; null si no es un importe positivo con 2 decimales como mucho
function importe(texto) {
  let t = texto.replace(/\s|€/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  if (!/^\d+(\.\d{1,2})?$/.test(t)) return null;
  const n = Number(t);
  return n > 0 ? n : null;
}

const cobros = [];
const noImportados = [];
const vistas = new Set();

filas.forEach((f, i) => {
  // Línea del fichero: la 1 es la cabecera
  const linea = i + 2;
  const operacion = limpio(f.operacion);
  const estado = limpio(f.estado).toUpperCase();
  const datos = { linea, operacion, fecha: limpio(f.fecha), hora: limpio(f.hora), importe: limpio(f.importe) };

  if (estado !== 'APROBADA') {
    noImportados.push({ ...datos, motivo: estado || 'sin estado' });
    return;
  }
  const fecha = fechaISO(datos.fecha);
  const euros = importe(datos.importe);
  const falla = !fecha ? 'fecha' : euros == null ? 'importe' : !operacion ? 'operación' : null;
  if (falla) {
    noImportados.push({ ...datos, motivo: `fila no válida (${falla})` });
    return;
  }
  if (vistas.has(operacion)) {
    noImportados.push({ ...datos, motivo: 'operación repetida en el CSV' });
    return;
  }
  vistas.add(operacion);
  cobros.push({ linea, operacion, fecha, hora: datos.hora, importe: euros });
});

// Rango de fechas para el GET; sin cobros válidos, hoy
const hoy = DateTime.now().setZone('Europe/Madrid').toISODate();
const fechas = cobros.map(c => c.fecha).sort();
const rango = fechas.length ? { desde: fechas[0], hasta: fechas[fechas.length - 1] } : { desde: hoy, hasta: hoy };

return [{ json: { origen, filas: filas.length, cobros, no_importados: noImportados, rango } }];

// Code «Decidir qué crear» (11 · Datáfono) · Run Once for All Items
// Compara los cobros válidos con las ventas de la app de esos días (regla de duplicados, pasos 8 y 9 de la spec).
// Devuelve un item por venta a crear { cuerpo, operacion, plan } o, si no hay ninguna, { cuerpo: null, plan }.

const revision = $('Revisar los cobros').first().json;

// Una lista vacía llega como un item vacío (Always Output Data): se ignora
const ventasApp = $('Leer ventas de esos días').all().map(i => i.json).filter(v => v && v.id != null);

const PREFIJO = 'Datáfono op. ';
const centimos = n => Math.round(Number(n) * 100);
const clave = (fecha, importe) => `${String(fecha)}|${centimos(importe)}`;
const concepto = v => String(v.concepto ?? '').trim();

// Paso 8: ya importado por este flujo (mismo concepto y misma fecha)
const importados = [];
const pendientes = [];
for (const c of revision.cobros) {
  const venta = ventasApp.find(v => String(v.fecha) === c.fecha && concepto(v) === PREFIJO + c.operacion);
  if (venta) importados.push({ ...c, venta_id: venta.id });
  else pendientes.push(c);
}

// Paso 9: ventas «tarjeta» apuntadas a mano (no del datáfono), por fecha + importe
const aMano = {};
for (const v of ventasApp) {
  if (v.forma_pago !== 'tarjeta' || concepto(v).startsWith(PREFIJO)) continue;
  (aMano[clave(v.fecha, v.importe)] ??= []).push(v);
}
for (const lista of Object.values(aMano)) lista.sort((a, b) => a.id - b.id);

const grupos = {};
for (const c of pendientes) (grupos[clave(c.fecha, c.importe)] ??= []).push(c);

const registrados = [];
const crear = [];
for (const [k, lista] of Object.entries(grupos)) {
  // Los primeros por hora se dan por apuntados; se crean los que sobran
  lista.sort((a, b) => a.hora.localeCompare(b.hora) || a.linea - b.linea);
  const enApp = aMano[k] ?? [];
  lista.forEach((c, i) => {
    if (i < enApp.length) registrados.push({ ...c, venta_id: enApp[i].id, venta_concepto: concepto(enApp[i]) });
    else crear.push(c);
  });
  aMano[k] = enApp.slice(lista.length);
}

// Ventas «tarjeta» de la app que no se han emparejado con ningún cobro (solo informativo)
const sinCobro = Object.values(aMano).flat()
  .map(v => ({ id: v.id, fecha: String(v.fecha), concepto: concepto(v), importe: v.importe }))
  .sort((a, b) => a.fecha.localeCompare(b.fecha) || a.id - b.id);

crear.sort((a, b) => a.linea - b.linea);
const plan = { ...revision, importados, registrados, crear, sin_cobro: sinCobro };

const salida = crear.map(c => ({
  json: {
    cuerpo: { fecha: c.fecha, concepto: PREFIJO + c.operacion, importe: c.importe, forma_pago: 'tarjeta' },
    operacion: c.operacion,
    plan,
  },
}));

return salida.length ? salida : [{ json: { cuerpo: null, plan } }];

// Code «Preparar informe» (11 · Datáfono) · Run Once for All Items
// Recoge las respuestas de «Registrar ventas» (si se ejecutó) y devuelve { asunto, texto } para
// «Enviar informe del datáfono». Un 422 va al informe; cualquier otro error para el flujo.

const items = $('Decidir qué crear').all();
const plan = items[0].json.plan;

// Resultados de un nodo, o [] si no se ejecutó (rama false del IF)
function resultadosDe(nombre) {
  try {
    if ($(nombre).isExecuted === false) return [];
    return $(nombre).all();
  } catch (e) {
    return [];
  }
}

// Mensaje de la app: {"detail": "..."} o, si falla la validación, {"detail": [{msg: ...}]}
function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}

// Las respuestas llegan en el mismo orden que los items a crear (Batching de 1)
const aCrear = items.filter(i => i.json.cuerpo);
const creadas = [];
const rechazadas = [];
if (aCrear.length) {
  const resultados = resultadosDe('Registrar ventas');
  if (resultados.length !== aCrear.length) {
    throw new Error(`Registrar ventas: se esperaban ${aCrear.length} respuestas y llegaron ${resultados.length}`);
  }
  aCrear.forEach((item, i) => {
    const c = plan.crear.find(x => x.operacion === item.json.operacion);
    const r = resultados[i].json;
    if (r.statusCode >= 200 && r.statusCode < 300) {
      let b = r.body;
      if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
      creadas.push({ ...c, venta_id: b?.id ?? null });
    } else if (r.statusCode === 422) {
      rechazadas.push({ ...c, error: detalle(r.body) });
    } else {
      throw new Error(`Registrar ventas (operación ${c.operacion}): la app respondió ${r.statusCode}: ${detalle(r.body)}`);
    }
  });
}

// ---------- Texto del informe ----------

const dia = iso => iso.split('-').reverse().join('/');
const e = n => `${Number(n).toFixed(2)} €`;
const cuando = c => `${dia(c.fecha)}${c.hora ? ` ${c.hora}` : ''}`;
const seccion = (titulo, lineas) => `${titulo} (${lineas.length})\n${lineas.length ? lineas.join('\n') : '- Ninguna'}\n`;

const { desde, hasta } = plan.rango;
const periodo = desde === hasta ? `del ${dia(desde)}` : `del ${dia(desde)} al ${dia(hasta)}`;
const total = creadas.reduce((s, c) => s + Math.round(c.importe * 100), 0) / 100;

const texto = [
  `Importación del datáfono ${periodo} (${plan.origen === 'formulario' ? 'subido con el formulario' : 'ejecución programada'})`,
  '',
  `Filas en el CSV: ${plan.filas} · cobros aprobados válidos: ${plan.cobros.length}`,
  creadas.length ? '' : 'No se ha creado ninguna venta.\n',
  seccion(`VENTAS CREADAS · ${e(total)}`, creadas.map(c =>
    `- op. ${c.operacion} · ${cuando(c)} · ${e(c.importe)} → venta ${c.venta_id ?? '(sin id)'}`)),
  seccion('YA IMPORTADAS EN UNA EJECUCIÓN ANTERIOR', plan.importados.map(c =>
    `- op. ${c.operacion} · ${cuando(c)} · ${e(c.importe)} = venta ${c.venta_id}`)),
  seccion('YA REGISTRADAS EN LA TIENDA (venta con tarjeta del mismo día e importe)', plan.registrados.map(c =>
    `- op. ${c.operacion} · ${cuando(c)} · ${e(c.importe)} = venta ${c.venta_id} (${c.venta_concepto})`)),
  seccion('NO IMPORTADAS', plan.no_importados.map(n =>
    `- línea ${n.linea}${n.operacion ? ` · op. ${n.operacion}` : ''} · ${n.fecha || 'sin fecha'}${n.hora ? ` ${n.hora}` : ''} · ${n.importe || 'sin importe'} · ${n.motivo}`)),
  seccion('RECHAZADAS POR LA APP', rechazadas.map(c =>
    `- op. ${c.operacion} · ${cuando(c)} · ${e(c.importe)}. La app respondió: «${c.error}»`)),
  seccion('VENTAS CON TARJETA EN LA APP SIN COBRO EN EL DATÁFONO (no se toca nada)', plan.sin_cobro.map(v =>
    `- venta ${v.id} · ${dia(v.fecha)} · ${v.concepto} · ${e(v.importe)}`)),
  'Las ventas creadas llevan el concepto «Datáfono op. <operación>». Si alguna ya estaba apuntada con otra forma de pago u otro día, ahora está dos veces: revisadla en la app.',
].join('\n');

const asunto = `Datáfono ${periodo}: ${creadas.length} ventas creadas`;

return [{ json: { asunto, texto } }];
